create table xxcus.xxcmp_case_decisions (
    decision_id           number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    case_id               number not null enable,
    level_no              number not null enable,
    role_code             varchar2(30 byte),
    decided_by            varchar2(255 byte) not null enable,
    outcome               varchar2(30 byte) not null enable,
    decision_date         timestamp(6) default systimestamp not null enable,
    comments              varchar2(4000 byte),
    task_id               number,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxcmp_case_decisions
    add constraint xxcmp_case_decisions_ck1
        check ( outcome in ( 'APPROVED', 'REJECTED' ) ) enable;

alter table xxcus.xxcmp_case_decisions
    add constraint xxcmp_case_decisions_pk primary key ( decision_id )
        using index enable;


